package cn.linkdeck.adb;
import android.content.Context;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import android.animation.ValueAnimator;import android.view.animation.OvershootInterpolator;import java.util.function.*;
/** Relative volume gesture. Offset is a direction request, never an alleged TV volume. */
public final class VolumeGlide extends View {
 private final Paint p=new Paint(3);private final RectF track=new RectF();private final Handler handler=new Handler(Looper.getMainLooper());private final BooleanSupplier authorized,motion;private final IntConsumer step;private float offset=0,travel,centerX,centerY,r;private boolean dragging;private int direction;private ValueAnimator returning;private Shader knob,glow,glowLine;private final Runnable tick=new Runnable(){public void run(){if(!dragging||!isAttachedToWindow()||!hasWindowFocus()){stop(false);return;}if(direction!=0)step.accept(direction);handler.postDelayed(this,180);}};
 public VolumeGlide(Context c,BooleanSupplier allowed,IntConsumer step,BooleanSupplier motion){super(c);this.authorized=allowed;this.step=step;this.motion=motion;setFocusable(true);setClickable(true);setContentDescription("音量连续调节，向左减小、向右增大，松手回中。也可使用两侧扬声器按钮。");setMinimumHeight(dp(48));}
 private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
 protected void onSizeChanged(int w,int h,int ow,int oh){centerX=w/2f;centerY=h/2f;travel=Math.max(1,w/2f-dp(15));r=dp(8);track.set(dp(7),centerY-dp(11),w-dp(7),centerY+dp(11));knob=new LinearGradient(0,centerY-dp(12),0,centerY+dp(12),new int[]{AuroraStyle.mix(AuroraStyle.surface(),AuroraStyle.edge(),.32f),AuroraStyle.surface(),AuroraStyle.base()},null,Shader.TileMode.CLAMP);glow=new RadialGradient(0,0,dp(23),new int[]{AuroraStyle.alpha(AuroraStyle.glowStart(),128),AuroraStyle.alpha(AuroraStyle.glowEnd(),80),AuroraStyle.alpha(AuroraStyle.glowEnd(),0)},new float[]{0,.5f,1},Shader.TileMode.CLAMP);glowLine=AuroraGlow.gradient(track.left,track.top,track.right,track.bottom);}
 protected void onDraw(Canvas c){
  p.setStyle(Paint.Style.FILL);p.setShader(null);p.setColor(AuroraStyle.mix(AuroraStyle.base(),AuroraStyle.surface(),.5f));c.drawRoundRect(track,dp(12),dp(12),p);
  p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(AuroraStyle.alpha(AuroraStyle.edge(),55));c.drawRoundRect(track,dp(12),dp(12),p);p.setStyle(Paint.Style.FILL);
  float x=centerX+offset*travel;p.setShader(glowLine);p.setAlpha(255);c.drawRoundRect(Math.min(centerX,x),centerY-dp(2),Math.max(centerX,x)+1,centerY+dp(2),dp(2),dp(2),p);p.setShader(null);
  c.save();c.translate(x,centerY);p.setShader(glow);p.setAlpha(255);c.drawCircle(0,0,dp(23),p);c.restore();p.setShader(null);
  p.setColor(AuroraStyle.alpha(0xff000000,AuroraStyle.light()?28:110));c.drawRoundRect(x-dp(10),centerY-dp(10),x+dp(10),centerY+dp(14),dp(9),dp(9),p);
  p.setShader(knob);p.setAlpha(255);c.drawRoundRect(x-dp(10),centerY-dp(12),x+dp(10),centerY+dp(12),dp(9),dp(9),p);p.setShader(null);
  p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setShader(glowLine);p.setAlpha(255);c.drawRoundRect(x-dp(10),centerY-dp(12),x+dp(10),centerY+dp(12),dp(9),dp(9),p);
  p.setShader(null);p.setColor(AuroraStyle.alpha(AuroraStyle.edge(),150));for(int i=-1;i<=1;i++)c.drawLine(x+dp(i*3),centerY-dp(3),x+dp(i*3),centerY+dp(3),p);p.setStyle(Paint.Style.FILL);
 }
 public boolean onTouchEvent(MotionEvent e){if(!isEnabled())return false;int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){if(!authorized.getAsBoolean())return true;if(returning!=null)returning.cancel();dragging=true;getParent().requestDisallowInterceptTouchEvent(true);update(e.getX());handler.postDelayed(tick,180);return true;}if(action==MotionEvent.ACTION_MOVE&&dragging){update(e.getX());return true;}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){boolean was=dragging;stop(true);if(was&&action==MotionEvent.ACTION_UP)performClick();return true;}return true;}
 private void update(float x){offset=Math.max(-1,Math.min(1,(x-centerX)/travel));int next=Math.abs(offset)<.18f?0:offset>0?1:-1;if(next!=direction){direction=next;if(direction!=0)step.accept(direction);}invalidate();}
 public void feedback(int dir){if(dragging)return;if(returning!=null)returning.cancel();offset=dir*.38f;returnCenter();}
 private void returnCenter(){if(returning!=null)returning.cancel();if(!motion.getAsBoolean()||!isAttachedToWindow()){offset=0;invalidate();return;}returning=ValueAnimator.ofFloat(offset,0);returning.setDuration(300);returning.setInterpolator(new OvershootInterpolator(1.3f));returning.addUpdateListener(a->{offset=(Float)a.getAnimatedValue();invalidate();});returning.start();}
 private void stop(boolean animate){handler.removeCallbacks(tick);dragging=false;direction=0;if(animate)returnCenter();else{if(returning!=null)returning.cancel();offset=0;invalidate();}if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(false);}
 protected void onDetachedFromWindow(){stop(false);super.onDetachedFromWindow();}public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(!focus)stop(false);}
 public boolean performClick(){super.performClick();return true;}
 public void onInitializeAccessibilityNodeInfo(AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_FORWARD);info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_BACKWARD);}
 public boolean performAccessibilityAction(int action,Bundle args){if(action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD||action==AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD){if(!isEnabled()||!authorized.getAsBoolean())return false;int dir=action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD?1:-1;step.accept(dir);feedback(dir);return true;}return super.performAccessibilityAction(action,args);}
}
